// Turn a raw Telegram update into a small, predictable object and check access.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const u = $input.first().json;
const msg = u.message;
const cb = u.callback_query;

let chat = null, from = null, kind = 'ignore', text = '', callback = null;
if (cb && cb.message) {
  chat = cb.message.chat; from = cb.from; kind = 'callback';
  callback = { id: String(cb.id), data: String(cb.data || ''), message_id: cb.message.message_id };
} else if (msg && typeof msg.text === 'string') {
  chat = msg.chat; from = msg.from; text = msg.text.trim();
  kind = text.startsWith('/') ? 'command' : 'text';
}
// Private chats only: a group would mix several learners into one user record.
if (!chat || chat.type !== 'private') return [];

let command = '', args = '';
if (kind === 'command') {
  const m = text.match(/^\/([a-zA-Z_]+)(?:@\w+)?(?:\s+([\s\S]*))?$/);
  if (m) { command = m[1].toLowerCase(); args = (m[2] || '').trim(); } else { kind = 'text'; }
}

const chatId = String(chat.id);
const owner = String(u.ownerChatId || '').trim();
const extra = String(u.allowedChatIds || '').split(',').map((s) => s.trim()).filter(Boolean);
const allowed = (owner !== '' && chatId === owner) || extra.includes(chatId);

const out = {
  chat_id: chatId,
  user_id: chatId,
  first_name: cut((from && from.first_name) || 'Learner', 60),
  kind, command, args, text, callback, allowed,
};
if (!allowed) {
  out.text = owner === ''
    ? `👋 Setup step: your chat ID is <code>${esc(chatId)}</code>.\nPaste it into the <b>Config</b> node as <b>ownerChatId</b>, save the workflow, then send /start again.`
    : `🔒 This is a private learning coach.\nYour chat ID is <code>${esc(chatId)}</code> — ask the owner to add it to <b>allowedChatIds</b>.`;
}
return [{ json: out }];

// One normalised "context" item per learner, whatever started the run:
//   Telegram message  -> 1 item for that user
//   Daily / Weekly    -> 1 item per active user

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const cfg = $('Config').first().json;
const source = cfg.source;
const NEEDS_GOAL = ['today', 'done', 'answer', 'progress', 'roadmap'];

const owner = String(cfg.ownerChatId || '').trim();
const extra = String(cfg.allowedChatIds || '').split(',').map((s) => s.trim()).filter(Boolean);
const isAllowed = (id) => (owner !== '' && id === owner) || extra.includes(id);

const normUser = (d, id, fallbackName) => ({
  id,
  name: d.name || fallbackName || 'Learner',
  email: d.email || '',
  timezone: d.timezone || cfg.timezone || 'Asia/Kolkata',
  study_time: d.study_time || cfg.defaultStudyTime || '19:00',
  paused: d.paused === true || d.paused === 'true',
  active_goal_id: d.active_goal_id || '',
  is_owner: id === owner,
  is_new: !d._id,
});

const out = [];

if (source === 'telegram') {
  const p = $('Parse Update').first().json;
  const d = $input.first().json || {};
  const user = normUser(d, p.user_id, p.first_name);
  const ctx = { source, action: 'reply', chat_id: p.chat_id, user_id: p.user_id, user, command: p.command, args: p.args, callback: p.callback, text: '' };

  if (p.kind === 'callback') {
    if (!p.callback.data.startsWith('q|')) return [];
    ctx.action = 'answer';
  } else if (p.kind === 'command') {
    const map = {
      start: 'profile', help: 'profile', email: 'profile', time: 'profile', pause: 'profile', resume: 'profile',
      goal: 'goal', today: 'today', next: 'today', done: 'done',
      progress: 'progress', stats: 'progress', roadmap: 'roadmap', plan: 'roadmap',
    };
    ctx.action = map[p.command] || 'reply';
    if (ctx.action === 'reply') ctx.text = `I don't know <code>/${esc(p.command)}</code>. Send /help to see what I can do.`;
    if (ctx.action === 'goal') {
      if (p.args.length < 8) {
        ctx.action = 'reply';
        ctx.text = 'Tell me what you want to learn, for example:\n<code>/goal Build production RAG apps. I know Python basics. 1.5 hours a day for 8 weeks.</code>';
      } else {
        ctx.args = cut(p.args, 700);
        ctx.ack = '🧠 Breaking your goal into skills and building a roadmap. This takes about a minute…';
      }
    }
  } else {
    ctx.text = user.active_goal_id
      ? 'Use /today for your session, /done when you finish it, or /help for everything else.'
      : 'To get started, send your goal like this:\n<code>/goal Learn SQL for data analysis, 1 hour a day for 4 weeks</code>';
  }

  if (NEEDS_GOAL.includes(ctx.action) && !user.active_goal_id) {
    if (ctx.action === 'answer') return [];
    ctx.action = 'reply';
    ctx.text = 'You have no active goal yet. Send:\n<code>/goal what you want to learn, hours per day, how many weeks</code>';
  }
  ctx.has_goal = NEEDS_GOAL.includes(ctx.action);
  out.push({ json: ctx });
} else {
  // Scheduled run: every approved, un-paused user with an active goal.
  for (const it of $input.all()) {
    const d = it.json || {};
    if (!d._id) continue;
    const id = String(d.chat_id || d._id);
    if (!isAllowed(id)) continue;
    const user = normUser(d, id, 'Learner');
    if (user.paused || !user.active_goal_id) continue;
    out.push({ json: { source, action: source === 'weekly' ? 'progress' : 'today', chat_id: id, user_id: id, user, command: '', args: '', callback: null, text: '', has_goal: true } });
  }
}
return out;

// Join each context item with its active goal document and decode stored fields.

// ── helpers ──
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
// Nested data is stored as JSON strings (see README: "Why *_json fields").
const parseJson = (s, d) => { if (s === null || s === undefined || s === '') return d; if (typeof s !== 'string') return s; try { return JSON.parse(s); } catch (e) { return d; } };
// Date-like strings come back from Firestore as timestamps: keep YYYY-MM-DD.
const day = (v) => (v ? String(v).slice(0, 10) : '');
// ─────────────
const ctxs = $('Context').all().map((i) => i.json);
const docs = $input.all().map((i) => i.json).filter((d) => d && d._id && String(d._name || '').includes('/goals/'));

const normGoal = (g) => ({
  id: g._id,
  title: g.title || 'Your goal',
  level: g.level || 'beginner',
  capstone: g.capstone || '',
  hours_per_day: num(g.hours_per_day, 1),
  minutes_per_session: num(g.minutes_per_session, 60),
  weeks: num(g.weeks, 1),
  days_per_week: num(g.days_per_week, 6),
  total_sessions: num(g.total_sessions, 0),
  current_session: num(g.current_session, 0),          // 0-based index into sessions[]
  session_status: g.session_status || 'pending',        // pending -> sent -> done -> (quiz) -> pending
  attempt: num(g.attempt, 1),
  remedial: g.remedial === true || g.remedial === 'true',
  status: g.goal_status || 'active',
  streak: num(g.streak, 0),
  best_streak: num(g.best_streak, 0),
  sessions_completed: num(g.sessions_completed, 0),
  start_date: day(g.start_date),
  last_done_date: day(g.last_done_date),
  last_sent_date: day(g.last_sent_date),
  current_quiz_id: g.current_quiz_id || '',
  skills: parseJson(g.skills_json, []),
  weeks_plan: parseJson(g.weeks_json, []),
  sessions: parseJson(g.sessions_json, []),
  resources: parseJson(g.resources_json, []),
  mastery: parseJson(g.mastery_json, {}),
  current_tasks: parseJson(g.current_tasks_json, null),
  last_misses: parseJson(g.last_misses_json, []),
});

const out = [];
for (const ctx of ctxs) {
  if (!ctx.has_goal) { out.push({ json: ctx }); continue; }
  const g = docs.find((d) => d._id === ctx.user.active_goal_id && String(d.user_id) === ctx.user_id);
  if (!g) {
    if (ctx.source !== 'telegram' || ctx.action === 'answer') continue;   // stay silent on schedules
    out.push({ json: { ...ctx, action: 'reply', text: 'I could not load your active goal. Send /goal to create a new one.' } });
    continue;
  }
  out.push({ json: { ...ctx, goal: normGoal(g) } });
}
return out;

// Every text reply passes through here. Telegram rejects messages over 4096 characters,
// so long ones are split at line breaks (every HTML tag opens and closes on one line).
const LIMIT = 3800;
const split = (text) => {
  const chunks = [];
  let cur = '';
  for (const line of String(text).split('\n')) {
    const piece = line.length > LIMIT ? line.slice(0, LIMIT) : line;
    if (cur !== '' && cur.length + piece.length + 1 > LIMIT) { chunks.push(cur); cur = piece; }
    else cur = cur === '' ? piece : cur + '\n' + piece;
  }
  if (cur.trim() !== '') chunks.push(cur);
  return chunks;
};
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  if (!j.chat_id) continue;
  const texts = Array.isArray(j.texts) ? j.texts : [j.text];
  for (const t of texts) {
    if (!t) continue;
    for (const c of split(t)) out.push({ json: { chat_id: j.chat_id, text: c } });
  }
}
return out;

// /start /help /email /time /pause /resume -> one user-document update + one reply.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// ─────────────
const out = [];
for (const it of $input.all()) {
  const ctx = it.json;
  const u = ctx.user;
  const now = new Date().toISOString();
  const row = { user_id: ctx.user_id, chat_id: ctx.chat_id, name: u.name, updated_at: now };
  const cols = ['chat_id', 'name', 'updated_at'];
  const set = (k, v) => { row[k] = v; if (!cols.includes(k)) cols.push(k); };
  if (u.is_new) { set('timezone', u.timezone); set('study_time', u.study_time); set('paused', false); set('created_at', now); }

  let text = '';
  const arg = String(ctx.args || '').trim();
  switch (ctx.command) {
    case 'email':
      if (/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]{2,}$/.test(arg) && arg.length <= 120) {
        set('email', arg.toLowerCase());
        text = `📧 Email set to <b>${esc(arg.toLowerCase())}</b>.\nYour roadmap, sessions and the weekly report will also arrive there when email delivery is enabled for this bot.`;
      } else if (arg.toLowerCase() === 'off') {
        set('email', ''); text = '📧 Email delivery turned off for you.';
      } else text = 'Usage: <code>/email you@example.com</code> (or <code>/email off</code>)';
      break;
    case 'time': {
      const m = arg.match(/^([01]?\d|2[0-3])[:.]([0-5]\d)$/);
      if (m) { const t = `${m[1].padStart(2, '0')}:${m[2]}`; set('study_time', t); text = `🕖 Study block set to <b>${t}</b> (${esc(u.timezone)}). Calendar events will use it.`; }
      else text = 'Usage: <code>/time 19:00</code> (24-hour clock)';
      break;
    }
    case 'pause': set('paused', true); text = '⏸ Paused. No daily messages until you send /resume. Your progress is kept.'; break;
    case 'resume': set('paused', false); text = '▶️ Resumed. Send /today for your current session.'; break;
    default:
      text = [
        `👋 Hi ${esc(u.name)}! I turn a learning goal into a roadmap, daily tasks, quizzes and progress tracking.`,
        '',
        '<b>Start</b>',
        '/goal <i>what you want to learn</i> — skills, roadmap and resources',
        '',
        '<b>Every day</b>',
        '/today — tasks for the current session',
        '/done — finished? take the quiz',
        '',
        '<b>Track</b>',
        '/progress — streak, scores, skill mastery',
        '/roadmap — the full plan',
        '',
        '<b>Settings</b>',
        '/email you@example.com — also receive sessions by email',
        '/time 19:00 — when to block study time in the calendar',
        '/pause · /resume — stop or restart daily messages',
      ].join('\n');
  }
  out.push({ json: { ...row, _columns: cols.join(','), text } });
}
return out;

// Stage 1 result -> validated plan outline. Never trust LLM numbers: clamp everything.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const base = $('Attach Goal').all().filter((i) => i.json.action === 'goal');
const out = [];
$input.all().forEach((it, i) => {
  const ctx = base[i].json;
  const o = it.json.output || (it.json.skills ? it.json : null);
  const fail = (text) => out.push({ json: { ...ctx, ok: false, text } });
  if (it.json.error || !o) return fail('⚠️ I could not analyse that goal just now (the AI model returned an error). Please send /goal again in a minute.');

  const rawSkills = Array.isArray(o.skills) ? o.skills.filter((s) => s && s.name) : [];
  if (o.is_valid === false || rawSkills.length < 2) {
    const q = o.clarify ? `\n\n${esc(cut(o.clarify, 300))}` : '';
    return fail(`🤔 I need a clearer learning goal to plan from.${q}\n\nExample:\n<code>/goal Become job-ready in backend development with Spring Boot. I know core Java. 2 hours a day for 10 weeks.</code>`);
  }

  const assumptions = (Array.isArray(o.assumptions) ? o.assumptions : []).map((a) => cut(a, 160)).slice(0, 6);
  const dpw = clamp(Math.round(num(o.days_per_week, 6)), 2, 7);
  let weeks = clamp(Math.round(num(o.weeks, 8)), 1, 26);
  const hours = clamp(Math.round(num(o.hours_per_day, 1.5) * 4) / 4, 0.25, 10);
  const MAX_SESSIONS = 120;
  if (weeks * dpw > MAX_SESSIONS) { weeks = Math.floor(MAX_SESSIONS / dpw); assumptions.push(`Plan capped at ${weeks} weeks to keep it manageable; extend with a follow-up goal.`); }

  // Re-number skill ids so later stages can rely on s1..sN.
  const idMap = {};
  rawSkills.slice(0, 10).forEach((s, k) => { idMap[String(s.id || '')] = `s${k + 1}`; });
  let skills = rawSkills.slice(0, 10).map((s, k) => ({
    id: `s${k + 1}`,
    name: cut(s.name, 90),
    why: cut(s.why || '', 220),
    prerequisites: (Array.isArray(s.prerequisites) ? s.prerequisites : []).map((p) => idMap[String(p)]).filter((p) => p && p !== `s${k + 1}`),
    difficulty: clamp(Math.round(num(s.difficulty, 3)), 1, 5),
    weight: Math.max(1, num(s.weight, 10)),
  }));
  const wsum = skills.reduce((a, s) => a + s.weight, 0);
  skills = skills.map((s) => ({ ...s, weight: Math.round((s.weight / wsum) * 100) }));

  const level = ['beginner', 'intermediate', 'advanced'].includes(String(o.level).toLowerCase()) ? String(o.level).toLowerCase() : 'beginner';
  const plan = {
    title: cut(o.goal_title || ctx.args, 100), raw_goal: ctx.args, level, hours_per_day: hours, minutes: Math.round(hours * 60),
    weeks, days_per_week: dpw, total_sessions: weeks * dpw, assumptions, capstone: cut(o.capstone || '', 300), skills,
  };
  // Input for stage 2 (Learning Roadmap).
  const llm_input = { goal: plan.title, level, weeks, days_per_week: dpw, total_sessions: plan.total_sessions,
    minutes_per_session: plan.minutes, capstone: plan.capstone,
    skills: skills.map((s) => ({ id: s.id, name: s.name, prerequisites: s.prerequisites, difficulty: s.difficulty, weight_percent: s.weight })) };
  out.push({ json: { ...ctx, ok: true, plan, llm_input } });
});
return out;

// Stage 2 result -> ordered list of study sessions. Sessions are not tied to calendar
// dates: the pointer only moves when a session is completed, so missed days never pile up.

// ── helpers ──
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const base = $('Merge Skills').all().filter((i) => i.json.ok === true);
const out = [];
$input.all().forEach((it, i) => {
  const ctx = base[i].json;
  const plan = ctx.plan;
  const o = it.json.output || (it.json.sessions ? it.json : null);
  const raw = o && Array.isArray(o.sessions) ? o.sessions.filter((s) => s && s.topic) : [];
  if (it.json.error || raw.length < 3) {
    out.push({ json: { ...ctx, ok: false, text: '⚠️ I could not build the roadmap just now (the AI model returned an incomplete plan). Please send /goal again.' } });
    return;
  }
  const ids = plan.skills.map((s) => s.id);
  const KINDS = ['learn', 'practice', 'build', 'review'];
  let last = ids[0];
  const sessions = raw.slice(0, plan.total_sessions).map((s, k) => {
    const sid = ids.includes(String(s.skill_id)) ? String(s.skill_id) : last;
    last = sid;
    return {
      n: k + 1,
      week: Math.floor(k / plan.days_per_week) + 1,
      skill_id: sid,
      topic: cut(s.topic, 110),
      objective: cut(s.objective || '', 220),
      kind: KINDS.includes(String(s.kind).toLowerCase()) ? String(s.kind).toLowerCase() : 'learn',
    };
  });
  const weeks = Math.ceil(sessions.length / plan.days_per_week);
  const rawWeeks = o && Array.isArray(o.weeks) ? o.weeks : [];
  const weeks_plan = [];
  for (let w = 1; w <= weeks; w++) {
    const r = rawWeeks.find((x) => num(x.week, -1) === w) || {};
    const first = sessions.find((s) => s.week === w);
    weeks_plan.push({ week: w, theme: cut(r.theme || (first ? first.topic : `Week ${w}`), 90), milestone: cut(r.milestone || '', 200) });
  }
  // Input for stage 3 (Resources): each skill with the topics it has to cover.
  const llm_input = { goal: plan.title, level: plan.level,
    skills: plan.skills.map((k) => ({ id: k.id, name: k.name, topics: sessions.filter((s) => s.skill_id === k.id).map((s) => s.topic).slice(0, 8) })) };
  out.push({ json: { ...ctx, ok: true, plan: { ...plan, weeks, total_sessions: sessions.length, sessions, weeks_plan }, llm_input } });
});
return out;

// Stage 3 result -> one item per resource so each link can be checked.
// LLMs invent URLs. Rules: https only, public hostnames only (no IPs / localhost, which
// also blocks SSRF via a crafted goal), and every resource carries a search link as a
// guaranteed-working fallback.

// ── helpers ──
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const ctx = $('Merge Roadmap').all().filter((i) => i.json.ok === true)[0].json;
const skills = ctx.plan.skills;
const first = $input.first().json;
const o = first.output || (first.resources ? first : null);
let raw = !first.error && o && Array.isArray(o.resources) ? o.resources.filter((r) => r && r.title) : [];

const safeUrl = (u) => {
  const s = String(u || '').trim();
  if (s.length > 300) return '';
  const m = s.match(/^https:\/\/([a-z0-9-]+(?:\.[a-z0-9-]+)+)(?::443)?(\/[^\s<>"']*)?$/i);
  if (!m) return '';
  const host = m[1].toLowerCase();
  if (/^[\d.]+$/.test(host)) return '';
  if (/(^|\.)(localhost|local|internal|lan|home|corp|test|invalid)$/.test(host)) return '';
  return s;
};
const KINDS = ['docs', 'course', 'video', 'paper', 'repo', 'book', 'practice', 'article'];

// If the model failed, fall back to pure search links per skill (still useful, never broken).
if (!raw.length) raw = skills.map((s) => ({ skill_id: s.id, title: `${s.name}: official docs and tutorials`, kind: 'docs', provider: 'Web search', url: '', search: `${s.name} official documentation tutorial`, why: 'Starting point for this skill.' }));

const ids = skills.map((s) => s.id);
const out = [];
raw.slice(0, 30).forEach((r, i) => {
  const sid = ids.includes(String(r.skill_id)) ? String(r.skill_id) : ids[0];
  const kind = KINDS.includes(String(r.kind).toLowerCase()) ? String(r.kind).toLowerCase() : 'docs';
  const skillName = (skills.find((s) => s.id === sid) || {}).name || '';
  const query = cut(r.search || `${r.title} ${skillName}`, 160);
  const search_url = (kind === 'video' ? 'https://www.youtube.com/results?search_query=' : 'https://www.google.com/search?q=') + encodeURIComponent(query);
  const url = safeUrl(r.url);
  out.push({ json: { i, skill_id: sid, title: cut(r.title, 120), kind, provider: cut(r.provider || '', 60), why: cut(r.why || '', 200), url, search_url, check_url: url || search_url } });
});
return out;

// Goal + skills + roadmap + checked resources -> one flat item that the Firestore
// nodes save, plus the Telegram summary and the roadmap email.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
// ─────────────
const ctx = $('Merge Roadmap').all().filter((i) => i.json.ok === true)[0].json;
const plan = ctx.plan;
const links = $('Prep Links').all().map((i) => i.json);
const checks = $input.all();

// Link status: 404/410 or DNS failure = dead -> swap in the search link.
// 401/403/405/429 usually mean "exists but blocks bots" -> keep, but unverified.
const resources = links.map((l, k) => {
  const c = (checks.find((x) => x.pairedItem && x.pairedItem.item === k) || checks[k] || {}).json || {};
  const code = num(c.statusCode, 0);
  const errText = c.error ? JSON.stringify(c.error) : '';
  const dead = code === 404 || code === 410 || /ENOTFOUND|EAI_AGAIN|ERR_INVALID_URL|404/.test(errText);
  const alive = code >= 200 && code < 400;
  const useSearch = !l.url || dead;
  return { skill_id: l.skill_id, title: l.title, kind: l.kind, provider: l.provider, why: l.why, url: useSearch ? l.search_url : l.url, verified: !useSearch && alive, is_search: useSearch };
});

const tz = ctx.user.timezone;
const now = DateTime.now().setZone(tz);
const goalId = 'g' + Date.now().toString(36);
const iso = new Date().toISOString();

// ── Telegram summary ──
const head = `✅ <b>Roadmap ready: ${esc(plan.title)}</b>\n${esc(plan.level)} · ${plan.hours_per_day} h/day · ${plan.days_per_week} days/week · ${plan.weeks} weeks · ${plan.total_sessions} sessions`;
const skillLines = plan.skills.map((s, k) => `${k + 1}. <b>${esc(s.name)}</b> (${s.weight}%)\n    ${esc(s.why)}`);
const weekLines = plan.weeks_plan.map((w) => `<b>W${w.week}</b> ${esc(w.theme)}${w.milestone ? `\n    → ${esc(w.milestone)}` : ''}`);
const texts = [
  [head, '', '<b>🧩 Skill breakdown</b>', ...skillLines].join('\n'),
  ['<b>🗺 Roadmap</b>', ...weekLines, plan.capstone ? `\n<b>🏁 Capstone</b>\n${esc(plan.capstone)}` : '',
    plan.assumptions.length ? `\n<i>Assumed: ${esc(plan.assumptions.join(' · '))}</i>` : '',
    '', `Send /today to start session 1 now. After that a session arrives every morning.\n/roadmap lists every session${ctx.user.email ? '; the full plan with resources is in your inbox' : ''}.`].filter((x) => x !== '').join('\n'),
];

// ── Email (full plan with resources) ──
const resBySkill = (sid) => resources.filter((r) => r.skill_id === sid);
const li = (r) => `<li><a href="${esc(r.url)}">${esc(r.title)}</a> <span style="color:#666">· ${esc(r.kind)}${r.provider ? ' · ' + esc(r.provider) : ''}${r.is_search ? ' · search link' : (r.verified ? ' · link checked' : '')}</span><br><span style="color:#444">${esc(r.why)}</span></li>`;
const email_html = [
  `<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;line-height:1.5;color:#1a1a1a">`,
  `<h2 style="margin-bottom:4px">${esc(plan.title)}</h2>`,
  `<p style="color:#555;margin-top:0">${esc(plan.level)} · ${plan.hours_per_day} h/day · ${plan.days_per_week} days/week · ${plan.weeks} weeks · ${plan.total_sessions} sessions</p>`,
  `<h3>Skills and resources</h3>`,
  ...plan.skills.map((s) => `<p style="margin-bottom:2px"><b>${esc(s.name)}</b> <span style="color:#666">(${s.weight}% of time, difficulty ${s.difficulty}/5)</span><br>${esc(s.why)}</p><ul style="margin-top:4px">${resBySkill(s.id).map(li).join('')}</ul>`),
  `<h3>Roadmap</h3>`,
  ...plan.weeks_plan.map((w) => `<p style="margin-bottom:2px"><b>Week ${w.week}: ${esc(w.theme)}</b>${w.milestone ? `<br><i>${esc(w.milestone)}</i>` : ''}</p><ol start="${(w.week - 1) * plan.days_per_week + 1}" style="margin-top:4px">${plan.sessions.filter((s) => s.week === w.week).map((s) => `<li>${esc(s.topic)} <span style="color:#666">· ${esc(s.kind)}</span></li>`).join('')}</ol>`),
  plan.capstone ? `<h3>Capstone</h3><p>${esc(plan.capstone)}</p>` : '',
  `<p style="color:#666;font-size:13px">Links marked "search link" open a search because no exact page could be confirmed.</p></div>`,
].join('');

return [{ json: {
  // Firestore: users/{user_id}/goals/{goal_id}
  goal_id: goalId, user_id: ctx.user_id, chat_id: ctx.chat_id, name: ctx.user.name,
  title: plan.title, raw_goal: plan.raw_goal, level: plan.level, capstone: plan.capstone,
  hours_per_day: plan.hours_per_day, minutes_per_session: plan.minutes, weeks: plan.weeks,
  days_per_week: plan.days_per_week, total_sessions: plan.total_sessions,
  assumptions_json: JSON.stringify(plan.assumptions), skills_json: JSON.stringify(plan.skills),
  weeks_json: JSON.stringify(plan.weeks_plan), sessions_json: JSON.stringify(plan.sessions),
  resources_json: JSON.stringify(resources), mastery_json: '{}', last_misses_json: '[]', current_tasks_json: '',
  current_session: 0, session_status: 'pending', attempt: 1, remedial: false, goal_status: 'active',
  streak: 0, best_streak: 0, sessions_completed: 0, current_quiz_id: '', current_topic: '',
  start_date: now.toISODate(), created_at: iso, updated_at: iso,
  // Firestore: users/{user_id}
  active_goal_id: goalId,
  // Outputs
  texts,
  send_email: !!ctx.user.email,
  email_to: ctx.user.email, email_subject: `Your learning roadmap: ${plan.title}`, email_html,
} }];

// Decide what "today" means for each learner:
//   generate -> new tasks from the LLM (new session, or a re-teach after a failed quiz)
//   resend   -> tasks already exist and are not finished: remind, do not regenerate
//   reply    -> nothing to send except a short message

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// ─────────────
const out = [];
for (const it of $input.all()) {
  const ctx = it.json;
  const g = ctx.goal;
  const scheduled = ctx.source !== 'telegram';
  const reply = (text) => { if (!scheduled) out.push({ json: { ...ctx, route: 'reply', text } }); };

  if (g.status === 'completed' || g.current_session >= g.total_sessions || !g.sessions[g.current_session]) {
    reply(`🎉 You have completed <b>${esc(g.title)}</b>. Send /progress for the final stats or /goal to start something new.`);
    continue;
  }
  const s = g.sessions[g.current_session];
  const skill = g.skills.find((k) => k.id === s.skill_id) || { id: s.skill_id, name: s.topic };
  const sess = { n: g.current_session + 1, total: g.total_sessions, week: s.week, topic: s.topic, objective: s.objective, kind: s.kind, skill_id: skill.id, skill_name: skill.name };

  if (g.session_status === 'done') {
    const text = `📝 Session ${sess.n} tasks are done; the quiz is still open.\nAnswer it above, or send /done for a fresh one.`;
    out.push({ json: { ...ctx, route: 'reply', text } });
    continue;
  }
  if (g.session_status === 'sent' && g.current_tasks && Array.isArray(g.current_tasks.tasks)) {
    out.push({ json: { ...ctx, route: 'resend', sess } });
    continue;
  }

  // Resources for this skill, checked links first. The model may only pick from this list.
  const res_list = g.resources.filter((r) => r.skill_id === skill.id).sort((a, b) => Number(b.verified) - Number(a.verified)).slice(0, 5);
  // Spaced recall: the previous topic plus the weakest skill so far.
  const recall = [];
  if (g.current_session > 0) recall.push(g.sessions[g.current_session - 1].topic);
  const weak = g.skills.map((k) => ({ name: k.name, m: g.mastery[k.id] })).filter((k) => typeof k.m === 'number' && k.m < 0.6 && k.name !== skill.name).sort((a, b) => a.m - b.m)[0];
  if (weak) recall.push(weak.name);

  const llm_input = {
    goal: g.title, level: g.level, minutes_budget: g.minutes_per_session,
    session: `${sess.n} of ${sess.total}`, session_kind: s.kind, skill: skill.name, topic: s.topic, objective: s.objective,
    recall,
    remedial: g.remedial === true,
    missed: g.remedial ? g.last_misses.slice(0, 6) : [],
    resources: res_list.map((r, i) => ({ index: i, title: r.title, kind: r.kind })),
  };
  out.push({ json: { ...ctx, route: 'generate', sess, res_list, llm_input } });
}
return out;

// Stage 5 result -> validated task list attached to the context.

// ── helpers ──
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const base = $('Plan Session').all().filter((i) => i.json.route === 'generate');
const KINDS = ['recall', 'learn', 'practice', 'build', 'review'];
const out = [];
$input.all().forEach((it, i) => {
  const ctx = base[i].json;
  const o = it.json.output || (it.json.tasks ? it.json : null);
  const raw = o && Array.isArray(o.tasks) ? o.tasks.filter((t) => t && t.title && t.instructions) : [];
  if (it.json.error || !raw.length) {
    out.push({ json: { ...ctx, ok: false, text: `⚠️ I could not prepare session ${ctx.sess.n} just now (the AI model returned an error). Send /today to try again.` } });
    return;
  }
  const tasks = raw.slice(0, 6).map((t) => {
    const r = ctx.res_list[Math.round(num(t.resource_index, -1))];
    return {
      title: cut(t.title, 100),
      kind: KINDS.includes(String(t.kind).toLowerCase()) ? String(t.kind).toLowerCase() : 'learn',
      minutes: clamp(Math.round(num(t.minutes, 20)), 5, 240),
      instructions: cut(t.instructions, 700),
      done_when: cut(t.done_when || '', 240),
      resource: r ? { title: r.title, url: r.url } : null,
    };
  });
  const pack = {
    session: ctx.sess.n,
    summary: cut(o.summary || '', 240),
    key_points: (Array.isArray(o.key_points) ? o.key_points : []).map((k) => cut(k, 200)).slice(0, 6),
    tasks,
  };
  out.push({ json: { ...ctx, ok: true, pack } });
});
return out;

// Tasks -> Telegram message, email, calendar block and the goal-state update.
// Email + calendar go out only on the first send of a day, so /today can be repeated safely.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
// ─────────────
const out = [];
for (const it of $input.all()) {
  const ctx = it.json;
  const g = ctx.goal;
  const sess = ctx.sess;
  const pack = ctx.pack || g.current_tasks;
  const fresh = !!ctx.pack;
  const tz = ctx.user.timezone;
  const now = DateTime.now().setZone(tz);
  const today = now.toISODate();
  const firstToday = g.last_sent_date !== today;
  const total = pack.tasks.reduce((a, t) => a + t.minutes, 0);
  const ICON = { recall: '🔁', learn: '📖', practice: '✍️', build: '🛠', review: '🧭' };

  // ── Telegram ──
  const header = fresh
    ? (g.remedial ? `🔄 <b>Session ${sess.n}/${sess.total}, second pass</b>` : `📚 <b>Session ${sess.n}/${sess.total}</b> · Week ${sess.week}`)
    : `⏰ <b>Session ${sess.n}/${sess.total} is still open</b>`;
  const lines = [header, `<b>${esc(sess.topic)}</b>`, `<i>${esc(sess.skill_name)}</i>`, `🎯 ${esc(sess.objective)}`];
  if (fresh && g.remedial) lines.push('<i>Last quiz was below the pass mark, so today re-teaches this topic from a different angle.</i>');
  lines.push('');
  pack.tasks.forEach((t, k) => {
    lines.push(`${ICON[t.kind] || '•'} <b>${k + 1}. ${esc(t.title)}</b> · ${t.minutes} min`);
    lines.push(esc(t.instructions));
    if (t.done_when) lines.push(`☑️ <i>Done when:</i> ${esc(t.done_when)}`);
    if (t.resource) lines.push(`🔗 <a href="${esc(t.resource.url)}">${esc(t.resource.title)}</a>`);
    lines.push('');
  });
  lines.push(`⏱ About ${total} min in total`);
  if (pack.summary) lines.push(`<i>${esc(pack.summary)}</i>`);
  lines.push('', 'When you finish, send /done for a short quiz.');

  // ── Email ──
  const email_html = [
    `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;line-height:1.5;color:#1a1a1a">`,
    `<p style="color:#666;margin-bottom:0">Session ${sess.n} of ${sess.total} · Week ${sess.week} · ${esc(g.title)}</p>`,
    `<h2 style="margin:4px 0">${esc(sess.topic)}</h2>`,
    `<p><b>Objective:</b> ${esc(sess.objective)}</p>`,
    ...pack.tasks.map((t, k) => `<div style="border-left:3px solid #4a6cf7;padding:2px 12px;margin:14px 0"><b>${k + 1}. ${esc(t.title)}</b> <span style="color:#666">· ${t.minutes} min · ${esc(t.kind)}</span><br>${esc(t.instructions)}${t.done_when ? `<br><i>Done when:</i> ${esc(t.done_when)}` : ''}${t.resource ? `<br><a href="${esc(t.resource.url)}">${esc(t.resource.title)}</a>` : ''}</div>`),
    `<p style="color:#444">About ${total} minutes in total. When you finish, open Telegram and send <b>/done</b> for the quiz.</p></div>`,
  ].join('');

  // ── Calendar: today at the learner's study time, or shortly from now if that has passed ──
  const [hh, mm] = String(ctx.user.study_time || '19:00').split(':').map((x) => num(x, 0));
  let start = now.set({ hour: hh, minute: mm, second: 0, millisecond: 0 });
  if (start < now.plus({ minutes: 5 })) start = now.plus({ minutes: 15 }).set({ second: 0, millisecond: 0 });
  const end = start.plus({ minutes: clamp(total, 15, 480) });
  const event_description = [`${g.title} · session ${sess.n}/${sess.total}`, `Objective: ${sess.objective}`, '',
    ...pack.tasks.map((t, k) => `${k + 1}. ${t.title} (${t.minutes} min)\n${t.instructions}${t.resource ? `\n${t.resource.url}` : ''}`), '', 'Finished? Send /done to the bot for the quiz.'].join('\n');

  out.push({ json: {
    chat_id: ctx.chat_id, text: lines.join('\n'),
    // Firestore: users/{user_id}/goals/{goal_id}
    user_id: ctx.user_id, goal_id: g.id, session_status: 'sent', current_tasks_json: JSON.stringify(pack),
    current_topic: sess.topic, last_sent_date: today, updated_at: new Date().toISOString(),
    send_email: firstToday && !!ctx.user.email,
    email_to: ctx.user.email, email_subject: `Session ${sess.n}: ${sess.topic}`, email_html,
    // Calendar events land on the owner's calendar, so only create them for the owner.
    make_event: firstToday && ctx.user.is_owner === true,
    event_start: start.toISO(), event_end: end.toISO(),
    event_summary: `Study: ${sess.topic}`, event_description,
  } });
}
return out;

// /done -> is there a session to quiz on? If yes, prepare the quiz-writer input.

// ── helpers ──
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
// ─────────────
const cfg = $('Config').first().json;
const out = [];
for (const it of $input.all()) {
  const ctx = it.json;
  const g = ctx.goal;
  const reply = (text) => out.push({ json: { ...ctx, route: 'reply', text } });
  if (g.status === 'completed' || !g.sessions[g.current_session]) { reply('🎉 This goal is already complete. Send /goal to start a new one.'); continue; }
  const pack = g.current_tasks;
  if (g.session_status === 'pending' || !pack || !Array.isArray(pack.tasks)) { reply('There is no open session yet. Send /today first, do the tasks, then /done.'); continue; }

  const s = g.sessions[g.current_session];
  const n = clamp(Math.round(num(cfg.questionsPerQuiz, 5)), 3, 8);
  const llm_input = {
    goal: g.title, level: g.level, topic: s.topic, objective: s.objective, question_count: n,
    key_points: pack.key_points || [],
    tasks_done: pack.tasks.map((t) => `${t.title}: ${t.instructions}`),
    retest: g.remedial ? g.last_misses.map((m) => m.concept).filter(Boolean).slice(0, 5) : [],
  };
  out.push({ json: { ...ctx, route: 'quiz', n, llm_input, ack: '📝 Nice work. Writing your quiz…' } });
}
return out;

// Stage 6 result -> validated quiz. The correct answer never leaves the server:
// buttons only carry quiz id + question index + option index.

// ── helpers ──
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const base = $('Check Done').all().filter((i) => i.json.route === 'quiz');
const out = [];
$input.all().forEach((it, i) => {
  const ctx = base[i].json;
  const g = ctx.goal;
  const o = it.json.output || (it.json.questions ? it.json : null);
  const raw = o && Array.isArray(o.questions) ? o.questions : [];
  const questions = [];
  for (const q of raw) {
    if (!q || !q.question || !Array.isArray(q.options)) continue;
    const opts = q.options.map((x) => cut(x, 220)).filter((x) => x !== '');
    const ci = Math.round(num(q.correct_index, -1));
    if (opts.length !== 4 || ci < 0 || ci > 3 || new Set(opts).size !== 4) continue;
    // Shuffle: models put the right answer in the same slot too often.
    const order = [0, 1, 2, 3];
    for (let a = 3; a > 0; a--) { const b = Math.floor(Math.random() * (a + 1)); [order[a], order[b]] = [order[b], order[a]]; }
    questions.push({ question: cut(q.question, 700), options: order.map((k) => opts[k]), correct_index: order.indexOf(ci), explanation: cut(q.explanation || '', 400), concept: cut(q.concept || ctx.goal.sessions[g.current_session].topic, 60) });
    if (questions.length >= ctx.n) break;
  }
  if (it.json.error || questions.length < 3) {
    out.push({ json: { ...ctx, ok: false, text: '⚠️ I could not write the quiz just now (the AI model returned an error). Send /done to try again.' } });
    return;
  }
  const s = g.sessions[g.current_session];
  const quizId = 'q' + Date.now().toString(36) + Math.floor(Math.random() * 36).toString(36);
  const iso = new Date().toISOString();
  out.push({ json: {
    ok: true, chat_id: ctx.chat_id, user_id: ctx.user_id,
    // Firestore: users/{user_id}/quizzes/{quiz_id}
    quiz_id: quizId, goal_id: g.id, session: g.current_session + 1, attempt_no: g.attempt, topic: s.topic, skill_id: s.skill_id,
    total: questions.length, quiz_status: 'open', questions_json: JSON.stringify(questions), created_at: iso,
    // Firestore: users/{user_id}/goals/{goal_id}
    session_status: 'done', current_quiz_id: quizId, updated_at: iso,
    questions,
  } });
});
return out;

// One Telegram message per question, each with A-D buttons.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// ─────────────
const out = [];
for (const it of $input.all()) {
  const j = it.json;
  const L = ['A', 'B', 'C', 'D'];
  j.questions.forEach((q, i) => {
    const head = i === 0 ? `📝 <b>Quiz: ${esc(j.topic)}</b>\nTap one answer per question. Your first tap counts.\n\n` : '';
    const text = `${head}<b>Q${i + 1}/${j.total}</b>  ${esc(q.question)}\n\n${q.options.map((o, k) => `<b>${L[k]})</b> ${esc(o)}`).join('\n')}`;
    out.push({ json: { chat_id: j.chat_id, text, cb0: `q|${j.quiz_id}|${i}|0`, cb1: `q|${j.quiz_id}|${i}|1`, cb2: `q|${j.quiz_id}|${i}|2`, cb3: `q|${j.quiz_id}|${i}|3` } });
  });
}
return out;

// A button tap -> grade that one question. Grading is plain code, not an LLM:
// multiple choice has one right answer, so it should be exact, instant and free.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
// Nested data is stored as JSON strings (see README: "Why *_json fields").
const parseJson = (s, d) => { if (s === null || s === undefined || s === '') return d; if (typeof s !== 'string') return s; try { return JSON.parse(s); } catch (e) { return d; } };
// ─────────────
const ctx = $('Attach Goal').all().filter((i) => i.json.action === 'answer')[0].json;
const quiz = $input.first().json || {};
const parts = String(ctx.callback.data).split('|');
const qi = Math.round(num(parts[2], -1));
const oi = Math.round(num(parts[3], -1));
const notify = (cb_text) => [{ json: { route: 'notify', callback_id: ctx.callback.id, cb_text } }];

if (!quiz._id || quiz._id !== parts[1] || String(quiz.user_id) !== ctx.user_id) return notify('This quiz is no longer available.');
const questions = parseJson(quiz.questions_json, []);
const q = questions[qi];
if (!q || oi < 0 || oi > 3) return notify('That button is not valid any more.');
if (quiz.quiz_status === 'evaluated') return notify('This quiz is already graded.');
const prev = quiz['a' + qi];
if (prev !== undefined && prev !== null && prev !== '') return notify('Already answered. Your first answer counts.');

const correct = oi === q.correct_index;
const L = ['A', 'B', 'C', 'D'];
const optLines = q.options.map((o, k) => {
  const mark = k === q.correct_index ? '✅' : (k === oi ? '❌' : '▫️');
  return `${mark} <b>${L[k]})</b> ${esc(o)}`;
});
const edit_text = `<b>Q${qi + 1}/${questions.length}</b>  ${esc(q.question)}\n\n${optLines.join('\n')}\n\n${correct ? '✅ <b>Correct</b>' : `❌ <b>Not quite</b>: you chose ${L[oi]}, the answer is ${L[q.correct_index]}`}${q.explanation ? `\n💡 ${esc(q.explanation)}` : ''}`;

const row = {
  route: 'save', callback_id: ctx.callback.id, cb_text: correct ? '✅ Correct' : '❌ Not quite',
  chat_id: ctx.chat_id, message_id: ctx.callback.message_id, edit_text,
  // Firestore: each answer is its own field (a0, a1, …) written with an update mask,
  // so two quick taps can never overwrite each other.
  user_id: ctx.user_id, quiz_id: quiz._id, _columns: 'a' + qi,
};
row['a' + qi] = oi;
return [{ json: row }];

// Runs after every saved answer. Stops quietly until the last question is answered,
// then scores the whole quiz (deterministically) and prepares the feedback prompt.

// ── helpers ──
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
// Nested data is stored as JSON strings (see README: "Why *_json fields").
const parseJson = (s, d) => { if (s === null || s === undefined || s === '') return d; if (typeof s !== 'string') return s; try { return JSON.parse(s); } catch (e) { return d; } };
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const cfg = $('Config').first().json;
const ctx = $('Attach Goal').all().filter((i) => i.json.action === 'answer')[0].json;
const quiz = $input.first().json || {};
if (!quiz._id || quiz.quiz_status === 'evaluated') return [];

const questions = parseJson(quiz.questions_json, []);
const answers = questions.map((q, i) => quiz['a' + i]);
if (!questions.length || answers.some((a) => a === undefined || a === null || a === '')) return [];

const results = questions.map((q, i) => {
  const chosen = Math.round(num(answers[i], -1));
  return { concept: q.concept, question: q.question, chosen: q.options[chosen] || '', correct_answer: q.options[q.correct_index], is_correct: chosen === q.correct_index };
});
const correct = results.filter((r) => r.is_correct).length;
const total = results.length;
const score = Math.round((correct / total) * 100);
const passMark = clamp(num(cfg.passScore, 60), 1, 100);
const g = ctx.goal;
// Only the goal's current quiz may move progress; an old quiz is graded as practice.
const stale = g.current_quiz_id !== quiz._id || g.session_status !== 'done';

return [{ json: {
  ...ctx,
  quiz_id: quiz._id, claimed_at: new Date().toISOString(),   // written by Claim Evaluation
  ev: { quiz_id: quiz._id, topic: quiz.topic || '', total, correct, score, passed: score >= passMark, pass_mark: passMark, stale, results,
    misses: results.filter((r) => !r.is_correct).map((r) => ({ concept: r.concept, question: cut(r.question, 200) })) },
  llm_input: { goal: g.title, level: g.level, topic: quiz.topic || '', score_percent: score, pass_mark: passMark,
    answers: results.map((r) => ({ concept: r.concept, question: r.question, learner_answer: r.chosen, correct_answer: r.correct_answer, is_correct: r.is_correct })) },
} }];

// Evaluation -> progress update. Writes three documents (quiz result, day log, goal state)
// and tells the learner what happens next.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cut = (s, n) => { const t = String(s ?? '').trim(); return t.length > n ? t.slice(0, n - 1).trimEnd() + '…' : t; };
// ─────────────
const ctx = $('Score Quiz').first().json;
const g = ctx.goal;
const ev = ctx.ev;
const first = $input.first().json || {};
const fb = first.error ? {} : (first.output || first || {});
const list = (a, n) => (Array.isArray(a) ? a : []).map((x) => cut(x, 260)).filter(Boolean).slice(0, n);
const feedback = { summary: cut(fb.summary || '', 400), strengths: list(fb.strengths, 3), gaps: list(fb.gaps, 5), next_steps: list(fb.next_steps, 3) };

const tz = ctx.user.timezone;
const now = DateTime.now().setZone(tz);
const today = now.toISODate();
const yesterday = now.minus({ days: 1 }).toISODate();
const iso = new Date().toISOString();
const idx = g.current_session;
const s = g.sessions[idx] || { topic: ev.topic, skill_id: '' };

const row = {
  chat_id: ctx.chat_id, user_id: ctx.user_id,
  // Firestore: users/{user_id}/quizzes/{quiz_id}
  quiz_id: ev.quiz_id, quiz_status: 'evaluated', score: ev.score, correct: ev.correct, passed: ev.passed,
  feedback_json: JSON.stringify(feedback), evaluated_at: iso, updated_at: iso,
  save_progress: !ev.stale,
};

const lines = [`📊 <b>Quiz result: ${ev.correct}/${ev.total} (${ev.score}%)</b> ${ev.stale ? '' : (ev.passed ? '✅ passed' : `❌ below the ${ev.pass_mark}% pass mark`)}`.trim()];
if (feedback.summary) lines.push(esc(feedback.summary));
if (feedback.strengths.length) lines.push('', '<b>Solid</b>', ...feedback.strengths.map((x) => `• ${esc(x)}`));
if (feedback.gaps.length) lines.push('', '<b>To fix</b>', ...feedback.gaps.map((x) => `• ${esc(x)}`));
if (feedback.next_steps.length) lines.push('', '<b>Next steps</b>', ...feedback.next_steps.map((x) => `• ${esc(x)}`));

if (ev.stale) {
  lines.push('', '<i>This was an older quiz, so it counts as practice and your progress is unchanged.</i>');
  return [{ json: { ...row, text: lines.join('\n') } }];
}

// ── Skill mastery: exponential moving average, so recent quizzes count more ──
const mastery = { ...g.mastery };
const old = mastery[s.skill_id];
mastery[s.skill_id] = Math.round((typeof old === 'number' ? 0.6 * old + 0.4 * (ev.score / 100) : ev.score / 100) * 1000) / 1000;

// ── Streak: consecutive calendar days (learner's timezone) with a finished quiz ──
let streak = g.streak;
if (g.last_done_date === today) streak = Math.max(streak, 1);
else if (g.last_done_date === yesterday) streak += 1;
else streak = 1;

// ── Adaptive pacing ──
// pass -> next session | fail -> same topic re-taught | 3rd fail -> move on, skill stays flagged weak
const MAX_ATTEMPTS = 3;
const forced = !ev.passed && g.attempt >= MAX_ATTEMPTS;
const advance = ev.passed || forced;
const nextIdx = advance ? idx + 1 : idx;
const completed = nextIdx >= g.total_sessions;

Object.assign(row, {
  // Firestore: users/{user_id}/days/{day_id}  (one row per quiz attempt = the progress log)
  day_id: `${g.id}_s${String(idx + 1).padStart(3, '0')}_a${g.attempt}`, goal_id: g.id, date: today, session: idx + 1,
  attempt_no: g.attempt, topic: s.topic, skill_id: s.skill_id, minutes: g.minutes_per_session, total: ev.total,
  // Firestore: users/{user_id}/goals/{goal_id}
  mastery_json: JSON.stringify(mastery), current_session: nextIdx, session_status: 'pending',
  attempt: advance ? 1 : g.attempt + 1, remedial: !advance, last_misses_json: JSON.stringify(advance ? [] : ev.misses),
  streak, best_streak: Math.max(g.best_streak, streak), last_done_date: today,
  sessions_completed: g.sessions_completed + (advance ? 1 : 0), goal_status: completed ? 'completed' : 'active',
  current_quiz_id: '', current_tasks_json: '',
});

lines.push('', `🔥 Streak: ${streak} day${streak === 1 ? '' : 's'} · Progress: ${row.sessions_completed}/${g.total_sessions} sessions`);
if (completed) lines.push('', `🎉 <b>Goal complete: ${esc(g.title)}</b>\nSend /progress for the final report, or /goal to start the next one.`);
else if (ev.passed) lines.push(`➡️ Next: session ${nextIdx + 1}, <b>${esc(g.sessions[nextIdx].topic)}</b>. Send /today now or wait for the morning message.`);
else if (forced) lines.push(`➡️ Three attempts on this topic, so we move on to <b>${esc(g.sessions[nextIdx].topic)}</b>. It stays on your weak-skills list and will come back in recall tasks.`);
else lines.push('🔁 Next session re-teaches this topic from a different angle. Send /today to do it now.');

return [{ json: { ...row, text: lines.join('\n') } }];

// Progress report from the day log + goal state. Same numbers for /progress (Telegram)
// and the weekly report (Telegram + email).

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Firestore returns integers as strings through the n8n node, so coerce.
const num = (v, d = 0) => { const n = Number(v); return v === null || v === '' || !Number.isFinite(n) ? d : n; };
// Date-like strings come back from Firestore as timestamps: keep YYYY-MM-DD.
const day = (v) => (v ? String(v).slice(0, 10) : '');
const clamp = (n, lo, hi) => Math.min(hi, Math.max(lo, n));
const bar = (p, w = 10) => { const f = Math.round(clamp(p, 0, 1) * w); return '█'.repeat(f) + '░'.repeat(w - f); };
// ─────────────
const ctxs = $('Attach Goal').all().map((i) => i.json).filter((c) => c.action === 'progress');
const logs = $input.all().map((i) => i.json).filter((d) => d && d._id && String(d._name || '').includes('/days/'));
const out = [];

for (const ctx of ctxs) {
  const g = ctx.goal;
  const tz = ctx.user.timezone;
  const now = DateTime.now().setZone(tz);
  const today = now.toISODate();
  const mine = logs.filter((d) => String(d.user_id) === ctx.user_id && d.goal_id === g.id)
    .map((d) => ({ date: day(d.date), score: num(d.score, 0), passed: d.passed === true || d.passed === 'true', minutes: num(d.minutes, 0), skill_id: d.skill_id, session: num(d.session, 0) }));

  const avg = (a) => (a.length ? Math.round(a.reduce((x, y) => x + y, 0) / a.length) : null);
  const weekStart = now.minus({ days: 6 }).toISODate();
  const week = mine.filter((d) => d.date >= weekStart);
  const done = g.sessions_completed;
  const pct = g.total_sessions ? Math.round((done / g.total_sessions) * 100) : 0;

  // Pace: where the plan expected you to be by today vs where you are.
  const start = DateTime.fromISO(g.start_date || today, { zone: tz });
  const daysIn = Math.max(1, Math.floor(now.startOf('day').diff(start.startOf('day'), 'days').days) + 1);
  const expected = Math.min(g.total_sessions, Math.floor((daysIn * g.days_per_week) / 7));
  const delta = done - expected;
  const pace = g.status === 'completed' ? 'Goal complete 🎉' : delta >= 0 ? (delta === 0 ? 'On track' : `${delta} session${delta === 1 ? '' : 's'} ahead of plan`) : `${-delta} session${delta === -1 ? '' : 's'} behind plan`;
  const remaining = Math.max(0, g.total_sessions - done);
  const finish = now.plus({ days: Math.ceil((remaining * 7) / g.days_per_week) }).toFormat('d LLL yyyy');

  const skills = g.skills.map((k) => ({ name: k.name, m: typeof g.mastery[k.id] === 'number' ? g.mastery[k.id] : null }));
  const weak = skills.filter((k) => k.m !== null && k.m < 0.6).sort((a, b) => a.m - b.m);
  const current = g.sessions[g.current_session];

  const title = ctx.source === 'weekly' ? '🗓 <b>Weekly report</b>' : '📈 <b>Progress</b>';
  const lines = [
    `${title} · ${esc(g.title)}`,
    `<code>${bar(pct / 100, 14)}</code> ${pct}%  (${done}/${g.total_sessions} sessions)`,
    `📍 ${pace}${g.status === 'completed' ? '' : ` · projected finish ${finish}`}`,
    `🔥 Streak ${g.streak} day${g.streak === 1 ? '' : 's'} (best ${g.best_streak})`,
    `🧪 Quizzes ${mine.length} · average ${avg(mine.map((d) => d.score)) ?? '–'}% · pass rate ${mine.length ? Math.round((mine.filter((d) => d.passed).length / mine.length) * 100) : '–'}%`,
    `📅 Last 7 days: ${week.filter((d) => d.passed).length} sessions passed · ${week.reduce((a, d) => a + d.minutes, 0)} min planned study · average ${avg(week.map((d) => d.score)) ?? '–'}%`,
    '',
    '<b>Skill mastery</b>',
    ...skills.map((k) => `<code>${k.m === null ? '░'.repeat(10) : bar(k.m)}</code> ${k.m === null ? ' –  ' : String(Math.round(k.m * 100)).padStart(3, ' ') + '%'}  ${esc(k.name)}`),
  ];
  if (weak.length) lines.push('', `⚠️ Weakest: ${weak.slice(0, 3).map((k) => esc(k.name)).join(', ')}. These come back as recall tasks.`);
  if (current && g.status !== 'completed') lines.push('', `▶️ Up next: session ${g.current_session + 1}, <b>${esc(current.topic)}</b> (/today)`);

  const email_html = [
    `<div style="font-family:Arial,Helvetica,sans-serif;max-width:640px;line-height:1.5;color:#1a1a1a">`,
    `<h2 style="margin-bottom:4px">Weekly report: ${esc(g.title)}</h2>`,
    `<p style="margin-top:0;color:#555">${done}/${g.total_sessions} sessions (${pct}%) · ${esc(pace)} · streak ${g.streak} days</p>`,
    `<p><b>This week:</b> ${week.filter((d) => d.passed).length} sessions passed, ${week.length} quizzes, average ${avg(week.map((d) => d.score)) ?? '–'}%</p>`,
    `<table cellpadding="6" style="border-collapse:collapse;font-size:14px"><tr style="background:#f2f4f8"><th align="left">Skill</th><th align="left">Mastery</th></tr>`,
    ...skills.map((k) => `<tr><td style="border-bottom:1px solid #e5e5e5">${esc(k.name)}</td><td style="border-bottom:1px solid #e5e5e5">${k.m === null ? 'not started' : Math.round(k.m * 100) + '%'}</td></tr>`),
    `</table>`,
    weak.length ? `<p><b>Focus next week:</b> ${weak.slice(0, 3).map((k) => esc(k.name)).join(', ')}</p>` : '',
    current && g.status !== 'completed' ? `<p><b>Up next:</b> session ${g.current_session + 1}, ${esc(current.topic)}</p>` : '',
    `</div>`,
  ].join('');

  out.push({ json: { chat_id: ctx.chat_id, text: lines.join('\n'),
    send_email: ctx.source === 'weekly' && !!ctx.user.email,
    email_to: ctx.user.email, email_subject: `Weekly learning report: ${pct}% of ${g.title}`, email_html } });
}
return out;

// /roadmap -> every session grouped by week, with done / current markers.

// ── helpers ──
// Escape text for Telegram HTML / email HTML.
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// ─────────────
const out = [];
for (const it of $input.all()) {
  const ctx = it.json;
  const g = ctx.goal;
  const texts = [`🗺 <b>${esc(g.title)}</b>\n${g.sessions_completed}/${g.total_sessions} sessions done`];
  for (const w of g.weeks_plan) {
    const rows = g.sessions.filter((s) => s.week === w.week).map((s) => {
      const i = s.n - 1;
      const mark = i < g.current_session ? '✅' : (i === g.current_session && g.status !== 'completed' ? '▶️' : '▫️');
      return `${mark} ${s.n}. ${esc(s.topic)}`;
    });
    texts.push([`<b>Week ${w.week}: ${esc(w.theme)}</b>`, w.milestone ? `<i>${esc(w.milestone)}</i>` : '', ...rows].filter(Boolean).join('\n'));
  }
  if (g.capstone) texts.push(`🏁 <b>Capstone</b>\n${esc(g.capstone)}`);
  // Join weeks into one text; Prepare Reply splits it at line breaks if it is too long.
  out.push({ json: { chat_id: ctx.chat_id, text: texts.join('\n\n') } });
}
return out;
